import * as path from 'node:path';
import * as url from 'node:url';

const here = path.dirname(url.fileURLToPath(import.meta.url));

/** Repo root, resolved from this file rather than from `process.cwd()`. */
export const PACKAGE_ROOT = path.resolve(here, '..', '..');

/** Where the intentionally-failing specs and their configs live. Deliberately
 *  outside `testDir`, so this package's own suite never collects them. */
export const REPORT_SRC_DIR = path.join(PACKAGE_ROOT, 'report-src');

/** Where reports are written. Wiped and regenerated by tests/global-setup.ts
 *  on every run, gitignored, never committed. */
export const REPORTS_DIR = path.join(PACKAGE_ROOT, '.tmp-reports');

/**
 * Every report the suite asserts against. Each one is produced by really
 * running Playwright in global setup - none is a stored snapshot, so a
 * Playwright upgrade that changes the report schema fails the build here
 * instead of passing against stale JSON.
 */
export const REPORTS = {
  /** Ordering, nesting, and the ordinary statuses, from one plain run. */
  structural: 'structural',
  /** A spec file that fails to import: top-level errors, zero failed specs. */
  reportErrors: 'report-errors',
  /** A run that matched no tests at all. */
  empty: 'empty',
  /** Two projects, two blobs, one real merge-reports. */
  mergeMultiproject: 'merge-multiproject',
  /** Initial run + --grep rerun, merged from a cwd that is NOT the config's
   *  rootDir, so Playwright leaves the duplicate spec entries unmerged. */
  mergeRerunUnmerged: 'merge-rerun-unmerged',
  /** The very same two blobs, merged from the config's rootDir, so Playwright
   *  merges them into one spec with two tests[] entries. */
  mergeRerunMerged: 'merge-rerun-merged',
  /** A retry attempt abandoned mid-suite: status 'skipped' at retry 1. */
  abandonedRetry: 'abandoned-retry',
  /** Tests dropped from the queue with no result at all: empty results[]. */
  maxFailures: 'max-failures',
  /** Real 'interrupted' results, via the max-failures status overwrite. */
  interrupted: 'interrupted',
} as const;

export type ReportName = (typeof REPORTS)[keyof typeof REPORTS];

/** Absolute path to a generated report. */
export function reportPath(name: ReportName): string {
  return path.join(REPORTS_DIR, `${name}.json`);
}

/** Absolute path to a scratch file inside the reports dir, for the handful of
 *  non-report inputs (an unparseable file, a path that does not exist). */
export function scratchPath(name: string): string {
  return path.join(REPORTS_DIR, name);
}
